reference_solution:
def minimum_paint_cost(costs):
    previous = costs[0][:]
    for red, blue, green in costs[1:]:
        previous = [red + min(previous[1], previous[2]),
                    blue + min(previous[0], previous[2]),
                    green + min(previous[0], previous[1])]
    return min(previous)

